.dm-rdr-grip{position:absolute;left:0;right:0;top:-6px;z-index:3;height:12px;display:grid;place-items:center;cursor:ns-resize;touch-action:none;outline:0}
.dm-rdr-grip i{display:block;width:32px;height:4px;border-radius:2px;background:var(--dm-rail);opacity:0;transition:opacity var(--dm-t-fast),background var(--dm-t-fast)}
